async function focusedTurnEnded(workId,kind){await until(async()=>{const state=await store.read(),attempt=state.multisite.attempts.find(row=>row.work_id===workId),files=await sessionFiles(join(directory,'cloud/multisite-executions')),file=files.find(path=>path.includes('/'+attempt.session_id+'/'));if(!file)return false;const{stdout}=await promisify(execFile)('zstd',['-dc','--',file],{encoding:'buffer',maxBuffer:32*1024*1024});const rows=stdout.toString().trim().split('\n').map(JSON.parse),end=rows.findLast(row=>row.type==='turn/end'),user=rows.findLast(row=>row.type==='user/message');return end?.data?.reason?.kind===kind&&end.seq>user.seq},'actual current SDK turn '+kind)}
async function runFocusedUi(script,config,label,barrier=false){const driver=fork(fileURLToPath(new URL('./'+script,import.meta.url)),[origin,config],{cwd:process.cwd(),env:process.env,execArgv:[],stdio:['ignore','pipe','pipe','ipc']});children.push(driver);const stdout=[],stderr=[];driver.stdout.on('data',chunk=>stdout.push(chunk));driver.stderr.on('data',chunk=>stderr.push(chunk));let phase=false,failure;if(barrier)driver.on('message',message=>{if(message.kind==='context-read-ui-phase'&&(message.phase??message.name)==='human-continue-accepted'){void(async()=>{try{await writeFile(join(directory,label+'-actual-phase.json'),JSON.stringify({message,state:await store.read()},null,2));phase=true;driver.send({kind:'context-read-ui-ack',phase:'human-continue-accepted'})}catch(cause){failure=cause;driver.kill('SIGTERM')}})()}});const exit=await new Promise(resolve=>driver.once('exit',resolve));await writeFile(join(directory,label+'.stdout.log'),Buffer.concat(stdout));await writeFile(join(directory,label+'.stderr.log'),Buffer.concat(stderr));if(failure)throw failure;assert.equal(exit,0,Buffer.concat(stderr).toString());if(barrier)assert(phase)}
